          "text": "Serendipity is defined as 'the power that turns chance into success,' 'the power that seizes chance and transforms it into good fortune,' 'the ability to make fortunate discoveries by chance,' 'the attitude that produces desirable discoveries through chance,' and 'the ability to find valuable things one was not looking for,' among other definitions."
