              "text": "On the streets we live on, similar kinds of bags called 'luxury bags' ripple like waves, and the same songs play everywhere. Consuming luxury goods gives the illusion that one belongs to the class of people who use luxury goods. It is likely an expression of the desire to belong to the same set [set, panoplie] as they do. This is why Jean Baudrillard called this the panoply effect (Effet de panoplie). People consume not for use value but as signs."
